const body = $('Webhook').first().json.body || {};
const subject_id = body.subject_id || '0';
const subject_name = body.subject_name || '';
const allRows = items.map(i => i.json).filter(r => r && r.question);

if (allRows.length === 0) {
  return [{
    json: {
      subject_id,
      subject_name,
      selected_ids: [],
      questions_html: '<p style="text-align:center;color:#ef4444;font-size:16px;padding:40px;">⚠️ لا توجد أي أسئلة مخزنة في بنك هذه المادة بعد. يرجى رفع ملفات المحاضرات أولاً.</p>',
      answers_html: '<p style="text-align:center;color:#64748b;font-size:16px;padding:40px;">لا توجد إجابات متاحة.</p>'
    }
  }];
}

// Find maximum lecture number
const maxLecture = Math.max(...allRows.map(r => parseInt(r.lecture_number || 1, 10)));

function shuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function pickWithPreference(pool, count) {
  const unused = shuffle(pool.filter(q => !q.used));
  const used = shuffle(pool.filter(q => q.used));
  const picked = unused.slice(0, count);
  if (picked.length < count) {
    picked.push(...used.slice(0, count - picked.length));
  }
  return picked;
}

let selectedQuestions = [];

if (maxLecture > 3) {
  const recentLectures = [maxLecture - 2, maxLecture - 1, maxLecture];
  const recentPool = allRows.filter(r => recentLectures.includes(parseInt(r.lecture_number, 10)));
  const olderPool = allRows.filter(r => !recentLectures.includes(parseInt(r.lecture_number, 10)));

  let recentPicked = pickWithPreference(recentPool, 5);
  let olderPicked = pickWithPreference(olderPool, 5);

  // Backfill if one pool doesn't have 5
  if (recentPicked.length < 5 && olderPool.length > olderPicked.length) {
    const extraNeeded = 5 - recentPicked.length;
    const extraOlder = olderPool.filter(q => !olderPicked.some(op => op.id === q.id));
    olderPicked.push(...pickWithPreference(extraOlder, extraNeeded));
  } else if (olderPicked.length < 5 && recentPool.length > recentPicked.length) {
    const extraNeeded = 5 - olderPicked.length;
    const extraRecent = recentPool.filter(q => !recentPicked.some(rp => rp.id === q.id));
    recentPicked.push(...pickWithPreference(extraRecent, extraNeeded));
  }

  selectedQuestions = shuffle([...recentPicked, ...olderPicked]);
} else {
  selectedQuestions = pickWithPreference(allRows, 10);
}

// If total pool is less than 10, take all available
if (selectedQuestions.length === 0) {
  selectedQuestions = allRows.slice(0, 10);
}

function escapeHtml(str) {
  if (!str) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

const qItems = selectedQuestions.map(q => `<li style="margin-bottom:14px; font-size:15px; color:#101828;">${escapeHtml(q.question)}</li>`).join('');
const aItems = selectedQuestions.map(q => `<li style="margin-bottom:14px; font-size:14.5px; color:#1e293b;">${escapeHtml(q.answer)}</li>`).join('');

const questions_html = `<ol style="padding-right:20px; line-height:1.8; margin:0;">${qItems}</ol>`;
const answers_html = `<ol style="padding-right:20px; line-height:1.8; margin:0;">${aItems}</ol>`;
const selected_ids = selectedQuestions.map(q => q.id).filter(Boolean);

return [{
  json: {
    subject_id,
    subject_name,
    selected_ids,
    questions_html,
    answers_html
  }
}];

